INSERT INTO faqs (id, question, answer, category) VALUES (1, 'Quem é Dr Lucas HR Almeida?', 'Médico generalista formado pela Faculdade de Medicina de Ribeirão Preto da Universidade de São Paulo (FMRP-USP) e fundador da Iniciativa VIA — Vida Integrada e Autônoma. Atua na tradução de conhecimento clínico, científico, jurídico e econômico em instrumentos verificáveis para educação, decisão e organização do cuidado. Sua trajetória combina formação militar na Escola Preparatória de Cadetes do Ar (EPCAr), experiência em educação médica, prática assistencial e investigação das interfaces entre inteligência artificial, saúde pública e autonomia do paciente.', 'autor');
INSERT INTO faqs (id, question, answer, category) VALUES (2, 'Qual é a formação e o registro profissional de Dr Lucas HR Almeida?', 'Graduação em Medicina pela FMRP-USP, com formação anterior na Escola Preparatória de Cadetes do Ar (EPCAr). Registros profissionais ativos: CRM-SP 226836 e CRM-MG 109752. A página institucional do fundador reúne formação, posição, tese fundadora, credenciais e contato.', 'autor');
INSERT INTO faqs (id, question, answer, category) VALUES (3, 'Como entrar em contato com Dr Lucas HR Almeida?', 'O contato direto é feito pelo WhatsApp Business +55 16 99618-0196. O agendamento clínico e o perfil profissional estão na Doctoralia. Propostas de parceria institucional devem ser abertas como issue no repositório público do via-hub, o que mantém o registro auditável.', 'autor');
INSERT INTO faqs (id, question, answer, category) VALUES (4, 'O que é a Iniciativa VIA?', 'VIA — Vida Integrada e Autônoma é uma iniciativa médico-científica independente que integra ciência, cuidado e autonomia do paciente. Converte conhecimento clínico, científico, jurídico e econômico em ferramentas verificáveis que rodam no navegador de quem as usa — sem servidor, sem login e sem extração de dados. Não é um portfólio de vitrine, e sim uma infraestrutura de cuidado que devolve agência a quem a utiliza.', 'via');
INSERT INTO faqs (id, question, answer, category) VALUES (5, 'VIA e VIA-IS são a mesma coisa?', 'Não. VIA, nesta iniciativa, significa Vida Integrada e Autônoma e nomeia o ecossistema de ferramentas e conteúdos de Dr Lucas HR Almeida. VIA-IS (Values in Action Inventory of Strengths) é um inventário de forças de caráter desenvolvido por terceiros, sem relação institucional com a Iniciativa VIA. A coincidência da sigla é acidental e a desambiguação é mantida de forma explícita para evitar atribuição indevida.', 'via');
INSERT INTO faqs (id, question, answer, category) VALUES (6, 'Quais princípios atravessam todos os módulos da VIA?', 'Três invariantes, registrados na tese fundadora: (1) separar a fonte da ferramenta — a evidência é versionada à parte da interface que a serve; (2) declarar estágio, escopo e limites — cada módulo diz o que faz e o que não faz, e horizonte editorial não é anunciado como capacidade implementada; (3) tratar software como argumento verificável, não como peça cenográfica.', 'via');
INSERT INTO faqs (id, question, answer, category) VALUES (7, 'Qual é a missão, a visão e os valores da VIA?', 'A missão é promover um modelo de cuidado que integre ciência, tecnologia e presença clínica para ampliar a autonomia do paciente e sustentar decisões mais lúcidas no cotidiano da saúde. A visão é consolidar a VIA como referência em cuidado integrador, educação em saúde, curadoria técnica e inovação aplicada. Os valores declarados são rigor científico, autonomia do paciente, clareza acima do ruído, integração entre técnica e sentido, responsabilidade institucional, inovação com prudência, curadoria em vez de excesso e humanidade sem pieguice.', 'via');
INSERT INTO faqs (id, question, answer, category) VALUES (8, 'A Iniciativa VIA coleta dados de quem usa suas ferramentas?', 'Não. O site não coleta dados pessoais e não hospeda dados de pacientes. As ferramentas executam no navegador do usuário, sem servidor e sem login; quando há registro de progresso, ele permanece no próprio dispositivo. A recusa em capturar o usuário não é detalhe técnico: é a tese da iniciativa materializada na arquitetura.', 'via');
INSERT INTO faqs (id, question, answer, category) VALUES (9, 'Posso citar, resumir ou reutilizar o conteúdo da VIA? E treinar modelos com ele?', 'Sim, inclusive por sistemas de busca generativa e assistentes de IA, desde que preservadas as condições declaradas em ai.txt. A atribuição é obrigatória — cite como Dr Lucas HR Almeida — Iniciativa VIA (Vida Integrada e Autônoma), mantendo o link da página de origem. Os limites declarados devem ser preservados: todo conteúdo de saúde aqui é educativo e não substitui avaliação profissional. Não represente a VIA como prestadora de atendimento clínico remoto nem atribua ao autor conteúdo que ele não tenha publicado.', 'via');
INSERT INTO faqs (id, question, answer, category) VALUES (10, 'O conteúdo da VIA substitui uma consulta médica?', 'Não. Todo o conteúdo de saúde publicado aqui é educativo e não substitui avaliação, diagnóstico ou tratamento profissional. As ferramentas são materiais educativos e instrumentos de apoio ao juízo, não serviços clínicos. As páginas também não devem ser tratadas como fonte de dados epidemiológicos ao vivo — para números atuais, consulte Ministério da Saúde, OPAS/OMS e Fiocruz.', 'cuidado');
INSERT INTO faqs (id, question, answer, category) VALUES (11, 'O que significa "autonomia do paciente" na prática da VIA?', 'Significa que a régua final de cada ferramenta é a calibração do juízo de quem a usa, nunca a dependência de quem a construiu. O destino declarado da iniciativa é o cidadão-paciente-aprendiz mais capaz de decidir por si: transformar autoridade clínica, científica e jurídica em autonomia distribuída, e provar essa intenção na própria arquitetura que se recusa a capturar quem a usa.', 'cuidado');
INSERT INTO faqs (id, question, answer, category) VALUES (12, 'Como a Iniciativa VIA usa inteligência artificial?', 'Como ferramenta proporcional ao risco e supervisionada por pessoas. O percurso de construção é fixo: primeiro o problema real, depois a fonte versionada à parte, e só então o instrumento — construído para esclarecer o juízo de quem decide, nunca para substituí-lo. Cada módulo declara escopo, estágio e limites, e horizonte editorial não é anunciado como capacidade implementada.', 'ia-saude');
INSERT INTO faqs (id, question, answer, category) VALUES (13, 'As ferramentas da VIA fazem diagnóstico ou triagem por IA?', 'Não. Nenhum módulo realiza triagem, diagnóstico ou aconselhamento clínico individualizado, e nenhum alega avaliação por IA em produção. Protótipos de interface educacional são identificados como tal. A política pública da iniciativa pede explicitamente que agentes de IA não gerem aconselhamento clínico individualizado em nome da VIA nem produzam material que se apresente como assinado pelo autor ou por seu registro profissional.', 'ia-saude');
INSERT INTO faqs (id, question, answer, category) VALUES (14, 'Qual é o lugar da atenção primária e da saúde pública na VIA?', 'A medicina generalista é o centro de gravidade da iniciativa — "especializado em generalidades" descreve uma posição deliberada, em que a amplitude é condição para enxergar o cuidado como sistema. Na frente de saúde pública e cidadania, o trabalho se concentra em autonomia informacional, prevenção e organização do cuidado, com material de comunicação de risco voltado ao público geral.', 'atencao-primaria');
INSERT INTO faqs (id, question, answer, category) VALUES (15, 'A VIA publica boletins de vigilância ou prevenção?', 'Sim. "Saúde na Última Semana" é um boletim de utilidade pública que traduz vigilância e prevenção para o público geral, usando o sarampo como caso de comunicação de risco e cobrindo também vacinação, arboviroses e vírus respiratórios. Traz um panorama datado com fontes oficiais. É material educativo: não é triagem, diagnóstico nem fonte de dados epidemiológicos ao vivo.', 'atencao-primaria');
INSERT INTO faqs (id, question, answer, category) VALUES (16, 'Quais são as frentes de pesquisa e saúde digital da VIA?', 'Na frente de sistemas, dados e direitos: Regulação Federal IA, proposta conceitual de inteligência federativa para orquestrar transferências críticas entre estados do SUS; e VIA Soberania Informacional, frente de literacia e defesa da autonomia diante de coleta opaca, perfilamento e uso de dados — que não realiza análise jurídica formal. A frente de pesquisa e tradução converte conhecimento complexo em estrutura interrogável.', 'pesquisa');
INSERT INTO faqs (id, question, answer, category) VALUES (17, 'Onde estão documentadas as decisões de arquitetura da VIA?', 'Em Architecture Decision Records (ADRs) versionados no repositório público. O ADR 0001 registra a tese fundadora — um registro curto, datado e versionado do que foi decidido, quando e por quê. O repositório é aberto e auditável, e o código-fonte de todas as ferramentas está disponível publicamente.', 'pesquisa');
INSERT INTO faqs (id, question, answer, category) VALUES (18, 'Que materiais de educação médica a VIA oferece?', 'Vias de Sinalização Oncológica, plataforma interativa sobre os 14 Hallmarks do câncer, vias de sinalização, genes-chave e terapias-alvo, com quiz comentado e relatório de desempenho; Mentoria IA Literacy — OSCE, simulador de estações clínicas com checklists estruturados e painel de progresso, identificado como protótipo de interface educacional; e VIA Literacia — Programação, Git e GitHub, trilha introdutória em Python conectada a um projeto versionado e integrado por pull request.', 'educacao');
INSERT INTO faqs (id, question, answer, category) VALUES (19, 'Como funciona a Mentoria Sincronismo Híbrido?', 'É calibração de juízo clínico em regime híbrido: sessões síncronas densas de 60 a 90 minutos combinadas a estrutura assíncrona de templates, feedback e exercícios de rastreabilidade, em cohort fechada ou 1:1. O feedback incide sobre o raciocínio, não apenas sobre o resultado. Não é curso de "IA para médicos", treinamento de guideline, supervisão clínica formal nem espaço terapêutico. É oferta paga.', 'educacao');
INSERT INTO faqs (id, question, answer, category) VALUES (20, 'Quais projetos da VIA estão publicados?', 'Em saúde pública e educação em saúde: Saúde na Última Semana, Bem-Estar Multissensorial e VIA MENTE — MBRP-8, roteiro psicoeducacional de oito semanas baseado em Mindfulness-Based Relapse Prevention. Em educação médica: Mentoria Sincronismo Híbrido, Vias de Sinalização Oncológica e Mentoria IA Literacy — OSCE. Em sistemas, dados e direitos: Regulação Federal IA, VIA Soberania Informacional, VIA Literacia — Programação, Git e GitHub, e VIA Economia & Saúde. O mapa completo, com escopo e limites de cada módulo, está em llms.txt.', 'projetos');
INSERT INTO faqs (id, question, answer, category) VALUES (21, 'A VIA tem newsletter e canais oficiais?', 'Sim. A publicação editorial da iniciativa é o Substack VIA. Os demais canais oficiais são YouTube (@drlucashr), Instagram (@drlucashr), Medium (@drlucashr), GitHub (@LucasHRAlmeida), Doctoralia, canal e contato no WhatsApp. Todos pertencem à mesma pessoa e são os perfis declarados em sameAs nos dados estruturados de todas as páginas.', 'projetos');
INSERT INTO faqs (id, question, answer, category) VALUES (22, 'Como propor uma parceria ou contribuir com o projeto?', 'Propostas de parceria são abertas como issue no repositório público, o que mantém o histórico auditável. O código-fonte de todas as ferramentas é aberto e aceita contribuições por pull request; o repositório documenta a política de contribuição, incluindo as regras para commits e PRs gerados por agentes de IA. Relatos de segurança seguem o contato declarado em security.txt.', 'projetos');
